SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.icu_stay_id, pr.procedure_code, pr.procedure_date, pr.procedure_type, q.quintile, COUNT(pr.procedure_code) AS procedure_count, AVG(i.length_of_stay) AS avg_los, SUM(CASE WHEN p.dod IS NOT NULL THEN 1 ELSE 0 END) AS mortality_count FROM patients p JOIN icustays i ON p.subject_id = i.subject_id JOIN procedureevents pr ON pr.subject_id = p.subject_id AND pr.hadm_id = i.icu_stay_id JOIN quintiles q ON q.quintile BETWEEN 1 AND 5 AND (pr.procedure_date - i.intime) <= 48 AND (pr.procedure_date - i.intime) / 48 <= q.quartile END JOIN (SELECT subject_id, hadm_id, length_of_stay FROM icustays WHERE first_careunit = 'ICU') i ON i.subject_id = p.subject_id AND i.hadm_id = pr.hadm_id JOIN (SELECT subject_id, hadm_id, procedure_code, procedure_date, procedure_type FROM procedureevents WHERE procedure_type = 'Surgery') pr ON pr.subject_id = p.subject_id AND pr.hadm_id = i.hadm_id AND pr.procedure_date BETWEEN i.intime AND i.outtime GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.icu_stay_id, pr.procedure_code, pr.procedure_date, pr.procedure_type, q.quintile ORDER BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.icu_stay_id, q.quintile, procedure_count NULLS LAST;